import React, { useEffect, useRef, useState } from 'react';
import { useAuth } from '../context/AuthContext';

const Technologies = () => {
  const sectionRef = useRef(null);
  const { skills, loading } = useAuth();

  const defaultSkills = [
    { name: 'React.js', category: 'Frontend', color: '#61DAFB' },
    { name: 'JavaScript', category: 'Language', color: '#F7DF1E' },
    { name: 'PHP', category: 'Backend', color: '#777BB4' },
    { name: 'MySQL', category: 'Database', color: '#4479A1' },
    { name: 'Node.js', category: 'Backend', color: '#339933' },
    { name: 'Git', category: 'Tools', color: '#F05032' },
    { name: 'Python', category: 'Backend', color: '#3776AB' },
    { name: 'Laravel', category: 'Backend', color: '#FF2D20' },
    { name: 'Tailwind CSS', category: 'Styling', color: '#38BDF8' },
    { name: 'C++', category: 'Language', color: '#00599C' },
    { name: 'Java', category: 'Language', color: '#F8981D' },
    { name: 'Electron.js', category: 'Framework', color: '#47848F' }
  ];

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
    );

    const reveals = sectionRef.current?.querySelectorAll('.reveal');
    reveals?.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  return (
    <section id="technologies" ref={sectionRef} className="py-24 bg-[#0a1628] relative overflow-hidden">
      {/* Background elements */}
      <div className="absolute top-0 right-0 w-96 h-96 bg-blue-500/5 rounded-full blur-3xl"></div>
      <div className="absolute bottom-0 left-0 w-80 h-80 bg-purple-500/5 rounded-full blur-3xl"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="text-center mb-16 reveal">
          <span className="inline-block px-4 py-2 rounded-full bg-blue-500/10 text-blue-400 text-sm font-medium mb-4">
            Tech Stack
          </span>
          <h2 className="text-4xl sm:text-5xl font-bold text-white mb-6">
            Technologies <span className="gradient-text">We Use</span>
          </h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            We leverage modern technologies and tools to build scalable, 
            efficient, and maintainable web solutions.
          </p>
        </div>

        {/* Tech Grid */}
        <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-4 mb-16">
          {(skills.length > 0 ? skills : defaultSkills).map((tech, index) => (
            <div
              key={tech.name}
              className="reveal group"
              style={{ transitionDelay: `${index * 50}ms` }}
            >
              <div className="card-minimal rounded-xl p-4 text-center relative overflow-hidden">
                {/* Glow effect */}
                <div 
                  className="absolute inset-0 opacity-0 group-hover:opacity-20 transition-opacity duration-300 rounded-2xl"
                  style={{ background: `radial-gradient(circle at center, ${tech.color}, transparent)` }}
                ></div>

                <div className="relative z-10">
                  <div className="w-12 h-12 mx-auto mb-3 flex items-center justify-center text-gray-300 group-hover:scale-110 transition-transform duration-300" style={{ color: tech.color }}>
                    <svg viewBox="0 0 24 24" className="w-8 h-8" fill={tech.color}>
                      <circle cx="12" cy="12" r="10" />
                    </svg>
                  </div>
                  <h3 className="text-base font-semibold text-white mb-1">{tech.name}</h3>
                  <p className="text-xs text-gray-400">{tech.category}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Additional Info */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 reveal">
          <div className="card-minimal rounded-xl p-6 text-center">
            <div className="text-4xl font-bold gradient-text mb-2">Modern</div>
            <p className="text-gray-400 text-sm">Latest frameworks and libraries</p>
          </div>
          <div className="card-minimal rounded-xl p-6 text-center">
            <div className="text-4xl font-bold gradient-text mb-2">Scalable</div>
            <p className="text-gray-400 text-sm">Built for growth and performance</p>
          </div>
          <div className="card-minimal rounded-xl p-6 text-center">
            <div className="text-4xl font-bold gradient-text mb-2">Secure</div>
            <p className="text-gray-400 text-sm">Best practices in security</p>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Technologies;
